import {MACHINES,mergeFeed,numeric,status} from './data.js';
const API='https://api.thingspeak.com/channels/3002831/feeds.json?api_key=C2GJTGX8RHAHCTIU&results=8000';
const CACHE='dashboard2-readings-v1';
let readings={},feeds=[],busy=false,lastChecked=null,failed=false,installPrompt;
try{const cached=JSON.parse(localStorage.getItem(CACHE)||'{}');for(const m of MACHINES){const r=cached[m.field];if(r&&numeric(r.value)!==null&&Number.isFinite(r.time))readings[m.field]=r;}}catch{}
try{document.body.classList.toggle('light',localStorage.getItem('dashboard2-theme')==='light');}catch{}
const $=id=>document.getElementById(id);
function age(time){const min=Math.max(0,Math.floor((Date.now()-time)/60000));return min<1?'Just now':min<60?`${min}m ago`:min<1440?`${Math.floor(min/60)}h ${min%60}m ago`:`${Math.floor(min/1440)}d ago`;}
function spark(m,tone){const points=feeds.filter(f=>numeric(f[m.field])!==null&&Number.isFinite(Date.parse(f.created_at))).slice(-40).map(f=>numeric(f[m.field]));if(points.length<2)return '<span>Awaiting trend data</span>';const min=Math.min(...points),max=Math.max(...points),range=max-min||1;const path=points.map((v,i)=>`${i*300/(points.length-1)},${max===min?23:42-(v-min)/range*38}`).join(' ');const color=tone==='good'?'var(--good)':tone==='bad'?'var(--bad)':tone==='warn'?'var(--warn)':'var(--muted)';return `<svg viewBox="0 0 300 46" preserveAspectRatio="none" role="img" aria-label="Recent ${m.name} readings"><polyline points="${path}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`;}
function render(){let healthy=0,attention=0,missing=0;
 $('equipment').innerHTML=MACHINES.map(m=>{const r=readings[m.field],s=status(m,r);if(s.tone==='good')healthy++;else if(s.tone==='missing')missing++;else attention++;
 const value=r?r.value.toLocaleString(undefined,{minimumFractionDigits:1,maximumFractionDigits:1}):'—';const timing=r?age(r.time):'No valid reading';const exact=r?new Date(r.time).toLocaleString():'Waiting for a numeric value';const target=m.silo?'Operating range 5–95%':`Target ≥ ${m.target.toLocaleString()} TPH`;
 const top=`<div class="card-top"><span class="asset-icon" aria-hidden="true">${m.code}</span>${m.silo?`<h3>${m.name}</h3>`:''}<span class="status ${s.tone}">${s.label}</span></div>`;
 const valueBlock=`${m.silo?'':`<h3>${m.name}</h3>`}<div class="reading">${value}<small>${m.unit}</small></div><div class="target">${target}</div>`;
 const bottom=`<div class="card-bottom"><span title="${exact}">${timing}</span><span>${r?new Date(r.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):m.field==='field6'?'Source sends empty values':'Awaiting source'}</span></div>`;
 return m.silo?`<article class="card silo"><div>${top}${valueBlock}</div><div><div class="level-track" role="img" aria-label="Silo level ${r?value+' percent':'unavailable'}"><div class="level-fill" style="width:${r?Math.max(0,Math.min(100,r.value)):0}%;background:${s.tone==='good'?'var(--good)':s.tone==='bad'?'var(--bad)':'var(--muted)'}"></div></div><div class="level-labels"><span>0% · Empty</span><span>100% · Full</span></div></div>${bottom}</article>`:`<article class="card">${top}${valueBlock}<div class="spark">${spark(m,s.tone)}</div>${bottom}</article>`;
 }).join('');$('healthy').textContent=String(healthy).padStart(2,'0');$('attention').textContent=String(attention).padStart(2,'0');$('unavailable').textContent=String(missing).padStart(2,'0');
 const coal=readings.field6;const messages=[];if(failed)messages.push('Connection unavailable. Showing saved readings where available; their original timestamps are preserved.');if(!coal)messages.push('Coal Mill: the source has no valid numeric reading in the available history. Empty values are ignored.');else if(status(MACHINES[5],coal).tone==='missing')messages.push('Coal Mill: showing the last valid reading. The source needs to resume numeric updates.');
 $('notice').hidden=!messages.length;$('notice').textContent=messages.join(' ');$('connection').textContent=failed?'Offline / connection issue':lastChecked?'Feed connected':'Connecting…';$('checked').textContent=lastChecked?`Checked ${new Date(lastChecked).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · 60s refresh`:'Refreshes every 60 seconds';
}
async function refresh(){if(busy)return;busy=true;$('refresh').disabled=true;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);try{const res=await fetch(API,{signal:controller.signal,cache:'no-store'});if(!res.ok)throw Error('Feed unavailable');const data=await res.json();if(!data||!Array.isArray(data.feeds))throw Error('Invalid feed');feeds=data.feeds;readings=mergeFeed(feeds,readings);lastChecked=Date.now();failed=false;try{localStorage.setItem(CACHE,JSON.stringify(readings));}catch{}}catch{failed=true;}finally{clearTimeout(timeout);busy=false;$('refresh').disabled=false;render();}}
$('refresh').addEventListener('click',refresh);$('theme').addEventListener('click',()=>{const light=document.body.classList.toggle('light');try{localStorage.setItem('dashboard2-theme',light?'light':'dark');}catch{}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true;}});window.addEventListener('appinstalled',()=>{$('install').hidden=true;});
window.addEventListener('online',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
render();refresh();setInterval(()=>{if(!document.hidden)refresh();},60000);setInterval(render,30000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
